#[cfg(not(target_arch = "wasm32"))]
const SHOW_PLAYER_NAMETAGS: bool = true;

/// Inject gamepad D-pad/A/B as synthesized key events into egui for menu navigation.
/// Free function to avoid borrowing all of GameState.
/// Returns true if gamepad A was pressed this frame (used to detect controller-driven Play).
/// Cross-platform: gamepad backend handles native gilrs / WASM Gamepad API uniformly.
/// Translate the first connected gamepad's d-pad/A/B into egui key events.
///
/// MUST be called with the `RawInput` BEFORE `ctx.begin_pass` — egui's focus
/// system (`Memory::Focus::begin_pass`) consumes Arrow/Tab keys from the
/// RawInput at the start of the pass. The previous version pushed events via
/// `ctx.input_mut` *after* the pass began: those reach `key_pressed()` checks
/// (so A=Enter activated the focused widget and B=Escape closed dialogs) but
/// never moved focus, leaving the d-pad a silent no-op on menus.
///
/// If no widget has focus yet, the first d-pad press is sent as Tab so egui
/// seeds focus on the first interactive widget; subsequent presses ride
/// egui's directional arrow-key navigation.
fn inject_gamepad_nav(
    ctx: &egui::Context,
    raw_input: &mut egui::RawInput,
    gamepad: &crate::gamepad::GamepadSystem,
) -> bool {
    if !gamepad.any_connected() { return false; }
    let (dpad_up, dpad_down, dpad_left, dpad_right) = gamepad.first_dpad();
    let first = gamepad.gamepads().iter().find(|g| g.connected);
    let a_pressed = first.map(|g| g.a_pressed).unwrap_or(false);
    let b_pressed = first.map(|g| g.b_pressed).unwrap_or(false);
    let nothing_focused = ctx.memory(|m| m.focused().is_none());
    let any_dir = dpad_up || dpad_down || dpad_left || dpad_right;

    let mut push = |key: egui::Key| {
        raw_input.events.push(egui::Event::Key {
            key, pressed: true, repeat: false,
            modifiers: egui::Modifiers::NONE, physical_key: None,
        });
    };
    if any_dir && nothing_focused {
        push(egui::Key::Tab); // seed focus, don't move yet
    } else {
        let pairs = [
            (dpad_up, egui::Key::ArrowUp),
            (dpad_down, egui::Key::ArrowDown),
            (dpad_left, egui::Key::ArrowLeft),
            (dpad_right, egui::Key::ArrowRight),
        ];
        for (pressed, key) in pairs {
            if pressed { push(key); }
        }
    }
    if a_pressed { push(egui::Key::Enter); }
    if b_pressed { push(egui::Key::Escape); }
    a_pressed
}

/// Map a live `PlayerSlot` to the wire `PlayerState` the cinematic replay records
/// (Phase 2c). Captures transform + health; held-item / skin / anim are deferred
/// (playback drives the Director camera over interpolated player targets, not
/// rendered avatars yet).
#[cfg(not(target_arch = "wasm32"))]
fn replay_player_state(idx: u32, slot: &crate::player_slot::PlayerSlot) -> crate::protocol::PlayerState {
    crate::protocol::PlayerState {
        player_index: idx,
        x: slot.player.pos.x,
        y: slot.player.pos.y,
        z: slot.player.pos.z,
        yaw: slot.camera.yaw,
        pitch: slot.camera.pitch,
        health: slot.combat.health,
        held_kind: 0,
        held_id: 0,
        anim_state: 0,
        flags: 0,
        skin_key: 0,
    }
}

